"use strict";(globalThis.webpackChunkgrc||=[]).push([[46976],{5646(e){e.exports=JSON.parse('{"citeKey":"pawar2026acropolis","slug":"pawar-2026-acropolis-1f2a","title":"Acropolis: A Portable, AI-Driven Semantic Search System for HPC","authors":["R. Pawar","L. Logan","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"LLM agents are now a primary interface to data repositories, but they locate files by issuing speculative regex queries through glob, grep, and file reads, creating a guess-and-check loop that is expensive in tool calls and tokens and ignores metadata embedded in scientific file formats. We present Acropolis, a semantic search system that augments a tiered filesystem with adaptive-depth content indexing and exposes it to agents through a typed natural-language interface. Acropolis provides a transparent file-summary operator in the I/O ingest path with content-addressable idempotency, a pluggable search-backend abstraction for lexical, vector, and graph engines, and an MCP server for compatible agents. On a 70-query CMIP6 retrieval benchmark, an agent using Acropolis matches the shell-tool baseline on retrieval accuracy while substantially reducing tool and backend calls per query and LLM token consumption.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2026/pawar-2026-acropolis-1f2a.pdf"},"tags":["Semantic Search","LLM Agents","HPC","Model Context Protocol"],"_projectIds":["iowarp","labios"],"grcSelected":false,"status":"presented","visibility":"public","projectIds":["iowarp","labios"],"memberAuthors":["pawar-rajni","logan-luke","cernuda-jaime","sun-xian-he","kougkas-anthony"],"funding":[{"agency":"NSF","award":"OAC-2411318","projectId":"iowarp"},{"agency":"NSF","award":"OAC-2313154","projectId":"labios"},{"agency":"NSF","award":"OAC-2320345"}]}')}}]);